CREATE OR REPLACE FUNCTION public.crm_quote_snapshot_matches(_quote uuid,_snapshot uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public AS $$
DECLARE v_snapshot jsonb; v_current jsonb; v_saved jsonb; v_table text; v_key text; v_proposal uuid;
BEGIN SELECT s.snapshot,p.id INTO v_snapshot,v_proposal FROM psa_proposal_snapshots s JOIN psa_proposals p ON p.id=s.proposal_id WHERE s.id=_snapshot AND p.quote_id=_quote AND s.kind='sent'; IF v_snapshot IS NULL THEN RETURN false; END IF;
SELECT to_jsonb(q)-ARRAY['quote_status','is_locked','locked_at','locked_project_id','pm_project_id','approved_at','signed_at','signed_method','signed_notes','updated_at','accepted_snapshot_id','acceptance_date','acceptance_note','acceptance_attachment_path','acceptance_actor','accepted_content_hash'] INTO v_current FROM fee_proposals q WHERE id=_quote;
v_saved:=(v_snapshot#>'{quote_data,raw,quote}')-ARRAY['quote_status','is_locked','locked_at','locked_project_id','pm_project_id','approved_at','signed_at','signed_method','signed_notes','updated_at','accepted_snapshot_id','acceptance_date','acceptance_note','acceptance_attachment_path','acceptance_actor','accepted_content_hash']; IF v_current IS DISTINCT FROM v_saved THEN RETURN false; END IF;
FOREACH v_table IN ARRAY ARRAY['quote_stages','quote_stage_dependencies','quote_allocations','quote_external_services','quote_payment_schedule_items','quote_billable_hourly_rates','quote_site_trips','quote_supplier_markups','quote_stage_supplier_costs'] LOOP
EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(r)-''updated_at'' ORDER BY r.id),''[]''::jsonb) FROM public.%I r WHERE quote_id=$1',v_table) INTO v_current USING _quote;
SELECT coalesce(jsonb_agg(value-'updated_at' ORDER BY value->>'id'),'[]'::jsonb) INTO v_saved FROM jsonb_array_elements(coalesce(v_snapshot#>ARRAY['quote_data','raw',v_table],'[]'::jsonb)); IF v_current IS DISTINCT FROM v_saved THEN RETURN false; END IF; END LOOP;
SELECT coalesce(jsonb_agg(to_jsonb(b)-'updated_at' ORDER BY b.id),'[]'::jsonb) INTO v_current FROM psa_proposal_blocks b WHERE b.proposal_id=v_proposal;
SELECT coalesce(jsonb_agg(value-'updated_at' ORDER BY value->>'id'),'[]'::jsonb) INTO v_saved FROM jsonb_array_elements(coalesce(v_snapshot->'blocks','[]'::jsonb)); RETURN v_current=v_saved; END $$;
REVOKE ALL ON FUNCTION public.crm_quote_snapshot_matches(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.crm_quote_snapshot_matches(uuid,uuid) TO authenticated,service_role;
DO $patch$ DECLARE v_definition text; BEGIN SELECT pg_get_functiondef('public.crm_quote_transition(uuid,text,date,text,uuid,text)'::regprocedure) INTO v_definition; v_definition:=replace(v_definition,'IF _attachment IS NOT NULL','IF NOT crm_quote_snapshot_matches(_quote,_snapshot) THEN RAISE EXCEPTION ''Accepted revision differs from current quote''; END IF; IF _attachment IS NOT NULL'); EXECUTE v_definition;
SELECT pg_get_functiondef('public.pm_convert_relative_quote(uuid,date,text)'::regprocedure) INTO v_definition; v_definition:=replace(v_definition,'IF q.accepted_content_hash IS DISTINCT','IF NOT crm_quote_snapshot_matches(_quote,q.accepted_snapshot_id) THEN RAISE EXCEPTION ''Accepted revision differs from current quote''; END IF; IF q.accepted_content_hash IS DISTINCT'); EXECUTE v_definition; END $patch$;